counts<-rbindlist(lapply(names(cohorts),function(k){d<-cohorts[[k]];data.table(analysis=k,N=nrow(d),patients=uniqueN(d$patient_id),patients_multiple_rows=sum(table(d$patient_id)>1),cancer_events=sum(d$cs_event),other_events=sum(d$other_event))}))
