warn_dir<-file.path(results_dir,'composition_decomposition','warning_audit')
w<-fread(file.path(warn_dir,'warnings.csv'));n<-fread(file.path(warn_dir,'warning_replicate_event_counts.csv'))
m<-merge(w,n,by='replicate')
stopifnot(nrow(m)==27,sum(grepl('variable  12',m$message))==24,sum(grepl('variable  19',m$message))==2)
